grok.supportRules:
_date %{date("yyyy-MM-dd'T'HH:mm:ss,SSS", "UTC"):timestamp}
_client_ip %{ipOrHost:network.client.ip}
_client_port %{port:network.client.port}
_method %{word:http.method}
_url %{notSpace:http.url}
_version HTTP\/%{regex("\\d+\\.\\d+"):http.version}
_status_code %{integer:http.status_code}
_bytes_written %{integer:network.bytes_written}
_log_level %{notSpace:level}
_worker_id %{integer:worker.id}
_model_name %{data:model.name}
_output %{notSpace:output}
_file_name %{notSpace:file.name}
_response_time %{integer:backend.response_time}
_inference_time %{integer:inference.time}
_job_backend_time %{integer:job.backend_time}
_job_waiting_time %{integer:job.waiting_time}
_job_done %{boolean:job.done}
_command_timestamp %{integer:command.timestamp}
_command_name %{notSpace:command.name}

_thread_name (W-%{_worker_id}-%{_model_name}(-%{_output})?|%{notSpace})
_torchserve_log_prefix (%{_date} \[%{_log_level}[ ]*] %{_thread_name:logger.thread_name})

_default_message %{data}
_backend_response_time_message (Backend response time: %{_response_time})
_job_time_message (Waiting time ns: %{_job_waiting_time}, Backend time ns: %{_job_backend_time})
_job_done_message (sent a reply, jobdone: %{_job_done})
_model_inference_message (Backend received inference at: %{_inference_time})
_flush_message (Flushing req.cmd %{_command_name} to backend at: %{_command_timestamp})

_torchserve_message (%{_backend_response_time_message}|%{_job_time_message}|%{_model_inference_message}|%{_job_done_message}|%{_flush_message}|%{_default_message})

_torchserve_log (%{_torchserve_log_prefix} (ACCESS_LOG|MODEL_LOG|%{_file_name}) - (%{_access_log:message}|%{_torchserve_message:message}))
_access_log (/%{_client_ip}:%{_client_port} "%{_method} %{_url} %{_version}" %{_status_code} (?>%{_bytes_written}|-))

grok.matchRules:
# Common
report_rule REPORT %{_request_id}\s+Duration: %{number:duration:scale(1000000)} ms\s+Billed Duration: %{number:lambda.billed_duration} ms\s+Memory Size: %{number:lambda. memorysize} MB\s+Max Memory Used: %{number:lambda.max_memory_used} MB(\s+Init Duration: %{number:lambda.init_duration} ms)?(\s+Runtime Duration: %{number:lambda.runtime_duration} ms\s+Post Runtime Duration: %{number:lambda.post_runtime_duration} ms)?%{data:xray:keyvalue(": ")}
# with slightly different order of attributes
report_rule_v2 REPORT %{_request_id}\s+Duration: %{number:duration:scale(1000000)} ms(\s+Runtime Duration: %{number:lambda.runtime_duration} ms\s+Post Runtime Duration: %{number:lambda.post_runtime_duration} ms)?\s+Billed Duration: %{number:lambda.billed_duration} ms\s+Memory Size: %{number:lambda. memorysize} MB\s+Max Memory Used: %{number:lambda.max_memory_used} MB(\s+Init Duration: %{number:lambda.init_duration} ms)?%{data:xray:keyvalue(": ")}

default_request_rule %{word:lambda.step}\s+%{_request_id}(\s+Version: %{notSpace:lambda.version})?

timeout_rule %{_timestamp}\s+%{notSpace:lambda.request_id:nullIf("undefined")}\s+%{regex("Task timed out"):error.message} after (%{number:duration:scale(1000000000)} seconds|%{number:duration:scale(1000000)} milliseconds)

process_error_rule %{_request_id} (%{regex("Process exited before completing request"):error.message}|%{regex("Error"):level}:%{data:error.message})

# Node
node_json_rule %{_timestamp}\s+%{notSpace:lambda.request_id:nullIf("undefined")}\s+(\[)?+%{word:level}+(\])?%{_trace_context}?(\s*Invoke Error\s*)?%{data::json}

# Python
python_rule \[%{word:level}\]?\s+%{_timestamp}\s+%{notSpace:lambda.request_id:nullIf("datadog_lambda_wrapper")}%{_trace_context}?.*
python_error %{regex("[^:]*"):error.message}: %{notSpace:error.kind}(\n|\s|\t)*Traceback \(most recent call last\):(?s)\s*%{data:error.stack}
python37_error \[%{regex("ERROR"):level}\] %{notSpace:error.kind}(: %{data:error.message})?(\n|\s|\t)*Traceback \(most recent call last\):(?s)\s*%{data:error.stack}

# Ruby
ruby_basic %{regex("[\\w]")},\s\[%{date("yyyy-MM-dd'T'HH:mm:ss.SSSSSS"):timestamp} #%{number}\]\s+%{word:level} --\s*: %{data::keyvalue}

fallback_json (%{date("yyyy-MM-dd'T'HH:mm:ss.SSSZ"):timestamp}|%{date("yyyy-MM-dd'T'HH:mm:ss.SSZ"):timestamp})\s+%{notSpace:lambda.request_id}\s+(%{word:level}:)?(%{data::json})

